out=[];g=9.8

def n(label,answer,unit,why,tol=None):
 return dict(label=label,type='numeric',answer=answer,unit=unit,tolerance=tol if tol is not None else max(abs(answer)*.01,1e-9),explanation=why)
def c(label,answer,wrong,why):
 options=[answer]+list(wrong)
 assert len(set(options))==len(options)
 return dict(label=label,type='choice',answer=answer,options=options,explanation=why)
def cross(r,f):return [r[1]*f[2]-r[2]*f[1],r[2]*f[0]-r[0]*f[2],r[0]*f[1]-r[1]*f[0]]
def vtext(v,unit):
 if not any(v):return '0 '+unit
 return '('+' + '.join(f'{a:g} '+b for a,b in zip(v,['î','ĵ','k̂']) if a).replace('+ -','− ')+') '+unit

def vec(label,v,unit,why):
 if any(v):wrong=[vtext([-x for x in v],unit),vtext([2*x for x in v],unit)]
 else:wrong=[vtext([1,0,0],unit),vtext([0,1,0],unit)]
 return c(label,vtext(v,unit),wrong,why)
